anager\": { \"optional\": true },\n    \"@deepseek-ai/dsh-client-ui-slots\": { \"optional\": true },\n    \"@deepseek-ai/dsh-client-ui-workspace\": { \"optional\": true },\n    \"react\": { \"optional\": true }\n  },\n  \"dependencies\": {\n    \"@deepseek-ai/schemastery\": \"^3.18.4\"\n  },\n  \"devDependencies\": {\n    \"vitest\": \"3.2.4\"\n  },\n  \"files\": [\n    \"lib\",\n    \"cordis.patch.yml\"\n  ]\n}\n"
