      "content": "window.__ModuleLoader__.load({\n  id: 'dsh-sticky-note',\n  factory: (require) => {\n    var module = { exports: {} }\n    var exports = module.exports\n    Object.defineProperty(exports, Symbol.toStringTag, { value: 'Module' })\n    let React = require('react')\n\n    const CHANNEL = '/dsh-sticky-note'\n\n    const CSS = `\n.sn-fab {\n  width: 28px;\n  height: 28px;\n  /* 不带任何 margin：slot 容器是 display:contents，本按钮直接成为宿主输入栏\n     .tools flex 容器的子项，间距由宿主 gap:16px 统一分配——与其他插件图标\n     （如语音按钮）天然等距，插件增删都自动适配 */\n  color: var(--dsw-alias-label-primary, #2b2b33);\n  cursor: pointer;\n  border: none;\n  border-radius: 999px;\n  flex: none;\n  place-items: center;\n  display: grid;\n  padding: 0;\n  background: var(--dsw-specific-selector, rgba(0, 0, 0, 0.06));\n  transition: background-color 0.12s ease;\n}\n.sn-fab:hover:not(:disabled) {\n  background: var(--dsw-alias-button-info-fill, #3b82f6);\n  color: #fff;\n}\n.sn-fab:active { transform: scale(0.94); }\n.sn-fab svg { display: block; }\n.sn-panel {\n  position: fixed;\n  z-index: 9999;\n  min-width: 240px;\n  min-height: 180px;\n  display: flex;\n  flex-direction: column;\n  background: rgba(255, 255, 255, 0.86);\n  backdrop-filter: blur(18px) saturate(1.2);\n  -webkit-backdrop-filter: blur(18px) saturate(1.2);\n  color: var(--dsw-alias-label-primary, #2b2b33);\n  border: 1px solid var(--dsw-alias-border-l2-darkmode-thin, rgba(0, 0, 0, 0.08));\n  border-radius: 18px;\n  box-shadow:\n    0 24px 60px rgba(0, 0, 0, 0.18),\n    0 4px 14px rgba(0, 0, 0, 0.1);\n  font-family: Inter, var(--dsw-font-family), system-ui, 'Segoe UI', sans-serif;\n  font-size: 13px;\n  animation: sn-pop 0.18s cubic-bezier(0.34, 1.56, 0.64, 1);\n  transform: scale(var(--sn-zoom, 1));\n  transform-origin: top left;\n  overflow: hidden;\n}\n/* 深色模式：玻璃面板换深色底，阴影加深（半透明底没有现成 alias token） */\nbody[data-ds-dark-theme] .sn-panel {\n  background: rgba(27, 27, 28, 0.92);\n  box-shadow:\n    0 24px 60px rgba(0, 0, 0, 0.55),\n    0 4px 14px rgba(0, 0, 0, 0.45);\n}\n/* 右下角缩放手柄：不画任何记号，只留一块透明的拖拽热区；鼠标与触摸共用 Pointer Events */\n.sn-rz-corner {\n  position: absolute;\n  right: 0;\n  bottom: 0;\n  width: 26px;\n  height: 26px;\n  cursor: nwse-resize;\n  z-index: 30;\n  border: 0;\n  padding: 0;\n  background: transparent;\n  touch-action: none;\n}\n@keyframes sn-pop {\n  from { opacity: 0; transform: scale(var(--sn-zoom-pop, 0.94)) translateY(6px); }\n  to { opacity: 1; transform: scale(var(--sn-zoom, 1)) translateY(0); }\n}\n.sn-head {\n  position: relative;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 8px 12px;\n  background: var(--dsw-alias-interactive-bg-hover, rgba(0, 0, 0, 0.04));\n  border-bottom: 1px solid var(--dsw-alias-border-l2-darkmode-thin, rgba(0, 0, 0, 0.06));\n  font-weight: 700;\n  font-size: 13.5px;\n  letter-spacing: 0.3px;\n  color: var(--dsw-alias-label-primary, #2b2b33);\n  flex: none;\n  cursor: move;\n  touch-action: none;\n  user-select: none;\n}\n.sn-head > span:first-child {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  min-width: 0;\n  flex: 1;\n  overflow: hidden;\n  white-space: nowrap;\n}\n.sn-head-title { flex: none; white-space: nowrap; }\n.sn-head-right { display: flex; align-items: center; flex: none; }\n.sn-head-actions-pop {\n  position: absolute;\n  z-index: 40;\n  top: 5px;\n  right: 8px;\n  /* 面板收窄时整排自动换行，不会顶出面板；右对齐让收起按钮停在原处 */\n  max-width: calc(100% - 16px);\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: flex-end;\n  align-items: center;\n  gap: 5px;\n  row-gap: 4px;\n  padding: 3px;\n  border: 1px solid var(--dsw-alias-border-l2-darkmode-thin, rgba(0, 0, 0, 0.12));\n  border-radius: 9px;\n  background: var(--dsw-specific-input-major, rgba(255, 255, 255, 0.96));\n  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.14);\n}\nbody[data-ds-dark-theme] .sn-head-actions-pop { background: rgba(38, 38, 40, 0.98); }\n.sn-actions-toggle { letter-spacing: 1px; font-weight: 700; }\n.sn-zoom-controls {\n  display: flex;\n  align-items: center;\n  gap: 2px;\n  padding: 0 2px;\n  border-radius: 7px;\n  background: var(--dsw-specific-selector, rgba(0, 0, 0, 0.05));\n}\n/* 倍率要放得下三位数 + 百分号；.sn-mini 的 22px 会盖掉同权重规则，这里用复合选择器提权 */\n.sn-mini.sn-zoom-value {\n  width: 40px;\n  min-width: 40px;\n  padding: 0;\n  font-size: 10.5px;\n  font-variant-numeric: tabular-nums;\n}\n.sn-mini {\n  border: 1px solid var(--dsw-alias-border-l2-darkmode-thin, rgba(0, 0, 0, 0.12));\n  background: var(--dsw-specific-selector, rgba(0, 0, 0, 0.05));\n  color: var(--dsw-alias-label-primary, #2b2b33);\n  width: 22px;\n  height: 22px;\n  border-radius: 6px;\n  cursor: pointer;\n  font-size: 13px;\n  line-height: 1;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 0;\n  transition: all 0.12s ease;\n}\n.sn-mini:hover { border-color: var(--dsw-alias-button-info-fill, #3b82f6); color: var(--dsw-alias-button-info-fill, #3b82f6); }\n.sn-mini.sn-on {\n  background: var(--dsw-alias-button-info-fill, #3b82f6);\n  border-color: transparent;\n  color: #fff;\n}\n.sn-pin-toggle { flex: none; }\n.sn-pin-toggle svg { width: 12px; height: 12px; }\n.sn-panel.sn-pinned { border-color: var(--dsw-alias-button-info-fill, #3b82f6); }\n.sn-x {\n  border: 1px solid var(--dsw-alias-border-l2-darkmode-thin, rgba(0, 0, 0, 0.12));\n  background: var(--dsw-specific-input-major, #fff);\n  color: var(--dsw-alias-label-secondary, #6b6b76);\n  width: 22px;\n  height: 22px;\n  border-radius: 6px;\n  cursor: pointer;\n  font-size: 13px;\n  line-height: 1;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 0;\n  transition: all 0.12s ease;\n}\n.sn-x:hover { border-color: var(--dsw-alias-button-info-fill, #3b82f6); color: var(--dsw-alias-button-info-fill, #3b82f6); }\n.sn-plus {\n  border: none;\n  background: var(--dsw-alias-button-info-fill, #3b82f6);\n  color: #fff;\n  width: 22px;\n  height: 22px;\n  border-radius: 6px;\n  cursor: pointer;\n  font-size: 14px;\n  font-weight: 700;\n  line-height: 1;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 0;\n  position: relative;\n  overflow: hidden;\n  transition: all 0.12s ease;\n}\n.sn-plus:hover { background: var(--dsw-alias-button-info-hover, #2563eb); transform: scale(1.06); }\n/* ＋ 与 ← 两枚字形叠放在同一个按钮里，切换时各自旋转淡出／淡入 */\n.sn-glyph {\n  position: absolute;\n  inset: 0;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  transition: transform 0.24s cubic-bezier(0.34, 1.4, 0.64, 1), opacity 0.16s ease;\n}\n.sn-glyph-back { transform: rotate(-120deg) scale(0.4); opacity: 0; }\n.sn-plus.sn-plus-back .sn-glyph-plus { transform: rotate(120deg) scale(0.4); opacity: 0; }\n.sn-plus.sn-plus-back .sn-glyph-back { transform: none; opacity: 1; }\n.sn-hist {\n  background: var(--dsw-specific-input-major, #fff);\n  border: 1px solid var(--dsw-alias-border-l2-darkmode-thin, rgba(0, 0, 0, 0.12));\n}\n.sn-hist:hover:not(.sn-active) { background: var(--dsw-alias-interactive-bg-hover-accent, #f5f9ff); border-color: var(--dsw-alias-button-info-fill, #3b82f6); }\n.sn-hist.sn-active { background: var(--dsw-alias-button-info-fill, #3b82f6); border-color: transparent; color: #fff; }\n.sn-openfolder {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 100%;\n  min-width: 0;\n  height: 28px;\n  box-sizing: border-box;\n  background: var(--dsw-specific-input-major, #fff);\n  border: 1px solid var(--dsw-alias-border-l2-darkmode-thin, rgba(0, 0, 0, 0.12));\n  color: var(--dsw-alias-label-secondary, #4a4a55);\n  border-radius: 10px;\n  cursor: pointer;\n  padding: 0;\n  transition: all 0.12s ease;\n}\n.sn-openfolder:hover { background: var(--dsw-alias-interactive-bg-hover-accent, #f5f9ff); border-color: var(--dsw-alias-button-info-fill, #3b82f6); color: var(--dsw-alias-button-info-fill, #3b82f6); }\n.sn-openfolder svg { flex: none; }\n.sn-back-text {\n  border: 1px solid var(--dsw-alias-border-l2-darkmode-thin, rgba(0, 0, 0, 0.12));\n  background: var(--dsw-specific-input-major, #fff);\n  color: var(--dsw-alias-label-primary, #2b2b33);\n  border-radius: 8px;\n  cursor: pointer;\n  padding: 4px 12px;\n  font-size: 12px;\n  font-weight: 600;\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  transition: all 0.12s ease;\n}\n.sn-back-text:hover {\n  border-color: var(--dsw-alias-button-info-fill, #3b82f6);\n  color: var(--dsw-alias-button-info-fill, #3b82f6);\n  background: var(--dsw-alias-interactive-bg-hover-accent, #f5f9ff);\n}\n.sn-help {\n  border: 1px solid var(--dsw-alias-border-l2-darkmode-thin, rgba(0, 0, 0, 0.12));\n  background: var(--dsw-specific-input-major, #fff);\n  color: var(--dsw-alias-label-secondary, #6b6b76);\n  width: 22px;\n  height: 22px;\n  border-radius: 6px;\n  cursor: pointer;\n  font-size: 13px;\n  font-weight: 700;\n  line-height: 1;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 0;\n  transition: all 0.12s ease;\n}\n.sn-help:hover { border-color: var(--dsw-alias-button-info-fill, #3b82f6); color: var(--dsw-alias-button-info-fill, #3b82f6); }\n.sn-help-body {\n  flex: 1;\n  min-height: 0;\n  overflow-y: auto;\n  padding: 12px 16px;\n  font-size: 13px;\n  line-height: 1.7;\n  color: var(--dsw-alias-label-primary, #2b2b33);\n}\n.sn-help-body p { margin: 0.45em 0; }\n.sn-help-strong {\n  font-weight: 700;\n  color: var(--dsw-alias-label-primary, #2b2b33);\n  word-break: break-all;\n}\n.sn-help-dim { color: var(--dsw-alias-label-tertiary, rgba(0, 0, 0, 0.45)); font-size: 12px; }\n.sn-body { display: flex; flex-direction: column; min-width: 0; min-height: 0; flex: 1; overflow: hidden; }\n.sn-text {\n  flex: 1;\n  min-width: 0;\n  min-height: 120px;\n  resize: none;\n  border: none;\n  outline: none;\n  background: transparent;\n  color: var(--dsw-alias-label-primary, #2b2b33);\n  padding: 12px 14px;\n  font-size: 13.5px;\n  line-height: 1.7;\n  font-family: inherit;\n  overflow-x: hidden;\n  overflow-y: auto;\n}\n.sn-text::placeholder { color: var(--dsw-alias-label-tertiary, rgba(43, 43, 51, 0.32)); }\n.sn-bar {\n  display: grid;\n  /* 三列等宽：面板拉宽/收窄时三个控件始终同宽，间距不变 */\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  align-items: center;\n  gap: 8px;\n  padding: 9px 12px;\n  border-top: 1px solid var(--dsw-alias-border-l2-darkmode-thin, rgba(0, 0, 0, 0.06));\n  background: var(--dsw-alias-interactive-bg-hover, rgba(0, 0, 0, 0.03));\n}\n/* 右侧留出 20px 给右下角那块透明缩放热区，避免徽章压在上面 */\n.sn-bar-3col { position: relative; padding-right: 20px; }\n.sn-send {\n  border: none;\n  background: var(--dsw-alias-button-info-fill, #3b82f6);\n  color: #fff;\n  border-radius: 10px;\n  cursor: pointer;\n  /* 撑满自己的那一列：三个控件永远同宽；窄面板下先压缩内边距再裁切 */\n  width: 100%;\n  min-width: 0;\n  padding: 0 6px;\n  height: 28px;\n  box-sizing: border-box;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 12.5px;\n  font-weight: 700;\n  line-height: 1;\n  letter-spacing: 0.5px;\n  white-space: nowrap;\n  overflow: hidden;\n  transition: background 0.12s ease, transform 0.1s ease;\n  box-shadow: 0 2px 8px rgba(59, 130, 246, 0.3);\n}\n.sn-send:hover { background: var(--dsw-alias-button-info-hover, #2563eb); transform: translateY(-1px); }\n.sn-send:active { transform: translateY(0) scale(0.97); }\n.sn-group { display: flex; align-items: center; gap: 5px; min-width: 0; }\n.sn-group > * { flex: 1 1 auto; min-width: 0; }\n.sn-iconbtn {\n  border: none;\n  background: var(--dsw-alias-interactive-bg-hover, rgba(0, 0, 0, 0.06));\n  color: var(--dsw-alias-label-secondary, #4a4a55);\n  border-radius: 10px;\n  cursor: pointer;\n  width: 100%;\n  min-width: 0;\n  padding: 0 6px;\n  height: 28px;\n  box-sizing: border-box;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 12.5px;\n  line-height: 1;\n  transition: background 0.12s ease;\n}\n.sn-iconbtn:hover { background: var(--dsw-alias-interactive-bg-hover-solid, rgba(0, 0, 0, 0.12)); }\n.sn-iconbtn.sn-active {\n  background: var(--dsw-al