{\n      return React.createElement('svg', { width: '16', height: '16', viewBox: '0 0 16 16', fill: 'none', 'aria-hidden': true, xmlns: 'http://www.w3.org/2000/svg' },\n        React.createElement('path', {\n          d: 'M1.5 3.5C1.5 2.94772 1.94772 2.5 2.5 2.5H5.5C5.77614 2.5 6.03934 2.6122 6.22804 2.80775L7.20711 3.82322C7.39581 4.01877 7.65901 4.13097 7.93515 4.13097H13.5C14.0523 4.13097 14.5 4.57869 14.5 5.13097V12.5C14.5 13.0523 14.0523 13.5 13.5 13.5H2.5C1.94772 13.5 1.5 13.0523 1.5 12.5V3.5Z',\n          stroke: 'currentColor',\n          strokeWidth: '1.2',\n          strokeLinejoin: 'round',\n        }),\n      )\n    }\n\n    function apply(ctx) {\n      const disposeStyle = installStyles()\n      const connection = ctx.get('connection')\n      if (connection === undefined) return\n      const call = (endpoint, payload) => connection.rpc.call(\n        '/api', 'dsh-sticky-note/call', { endpoint, payload: payload || {} },\n      ).catch(() => connection.rpc.call(CHANNEL, endpoint, payload || {}))\n      const rpc = (endpoint, payload) => call(endpoint, payload).then((result) => {\n        if (!result.ok) {\n          const error = result.error || {}\n          throw new Error(error.message || (typeof error.details === 'string' ? error.details : error.code) || 'rpc failed')\n        }\n        return result.value\n      })\n      const slots = ctx.get('slots')\n      if (slots === undefined) return\n      slots.inject('conversation.input.left', () => slots.register(\n        { name: 'conversation.input.left', id: 'sticky-note', order: 20 },\n        (zoneProps) => React.createElement(StickyNoteApp, {\n          rpc,\n          inputActions: (zoneProps && zoneProps.inputActions) || null,\n          useInput: (zoneProps && zoneProps.useInput) || null,\n        }),\n      ))\n      const settingsCard = () => React.createElement(SettingsCard, {\n        rpc,\n        workspaces: ctx.get('uiWorkspace'),\n      })\n      slots.inject('plugins.bundle.config', () => slots.register(\n        // 外部包的设置页收口在插件管理器：key 必须是包名。\n        { name: 'plugins.bundle.config', key: 'dsh-sticky-note' },\n        ({ view }) => view === 'page' ? settingsCard() : null,\n      ))\n      ctx.effect(() => disposeStyle, 'dsh-sticky-note: styles')\n    }\n\n    // 浏览器 Loader 会按此声明创建可见服务的 Cordis fiber。\n    // 没有这一项时模块会被下载，但 apply 无法拿到 slots/connection。\n    exports.inject = ['connection', 'slots', 'uiWorkspace']\n    exports.apply = apply\n    exports.StickyNoteApp = StickyNoteApp\n    exports.renderMarkdown = renderMarkdown\n    exports.parsePanelLayout = parsePanelLayout\n    exports.parsePanelZoom = parsePanelZoom\n    exports.panelZoomCommand = panelZoomCommand\n    exports.nextPanelZoom = nextPanelZoom\n    exports.clampPanelLayout = clampPanelLayout\n    exports.snapPanelLayout = snapPanelLayout\n    exports.headPrimaryAction = headPrimaryAction\n    return module.exports\n  },\n})\n"
